	int ret=-1025,l=1,r=n;
	while(l<=r){
		int mid=(l+r)>>1;
		if(x[mid]>=pos){
			ret=mid,r=mid-1;
		}
		else{
			l=mid+1;
		}
	}
	return ret;
}
