				if(nxt==-1025){
					time=-1025;
					break;
				}
				time-=abs(x[nxt]-pos),pos=x[nxt];
				if(time<0){
					break;
				}
				if(now>=a[nxt]){
					now+=a[nxt];
					if(nxt+1>n){
						break;
					} 
					int last=reach(nxt+1,n,time,pos);
					if(last==-1025){
						time=-1025;
						break;
					}
					//我们从nxt+1~last都可以到达 无需担心别的 接下来是极长段满足<=now 也就是max<=now;
					int l=nxt+1,r=last;
					last=-1025;
					while(l<=r){
						int mid=(l+r)>>1;
						if(rmq.query(nxt+1,mid)<=now){
							last=mid,l=mid+1;
						}
						else{
							r=mid-1;
						}
					} 
					if(last==-1025){
						pos++,time--;
					}
					else{//我们可以吃掉nxt+1~last的一切 
						now+=pre[last]-pre[nxt];
						time-=abs(x[last]-pos),pos=x[last],pos++,time--;
					}
				}
				else{
					turnleft=1;
					time-=abs(pos-origin),pos=origin;
					break; 
				}
			}	
			if(turnleft){

				//继续出发 向左边 
				while(1){
					int nxt=find2(pos);
					if(nxt==-1025){
						time=-1025;
						break;
					}
					time-=abs(x[nxt]-pos),pos=x[nxt];
					if(time<0){
						break;
					}
					if(now>=a[nxt]){
						now+=a[nxt];
						if(nxt==1){
							break;
						}
						int first=reach2(1,nxt-1,time,pos);
						if(first==-1025){
							time--,pos--;
						}
						else{//first~nxt-1的全部 
							now+=pre[nxt-1]-pre[first-1];
							time-=abs(pos-x[first]);
							pos=x[first];
							pos--,time--;
						}
					}
					else{
						break;
					}	
				}	
			} 
			cout<<now<<" ";
		}
		cout<<'\n';
	}
}

