}
struct segtree{
    struct node{
        int l,r,max,tag;
        node(){
            l=r=max=tag=0;
        }
    }t[N*4];
    void pushup(int u){
        t[u].max=max(t[u*2].max,t[u*2+1].max);
    }
    void build(int u,int l,int r){
        t[u].l=l,t[u].r=r;
        if(l==r){
            return;
        }
        int mid=(l+r)>>1;
        build(u*2,l,mid),build(u*2+1,mid+1,r),pushup(u);
    }
    void addtag(int u,int x){
        t[u].max+=x,t[u].tag+=x;
    }
    void pushdown(int u){
        addtag(u*2,t[u].tag),addtag(u*2+1,t[u].tag),t[u].tag=0;
    }
    void modify(int u,int l,int r,int x){
        if(t[u].l>=l&&t[u].r<=r){
            addtag(u,x);
            return;
        }
        pushdown(u);
        int mid=(t[u].l+t[u].r)>>1;
        if(l<=mid){
            modify(u*2,l,r,x);
        }
        if(r>mid){
            modify(u*2+1,l,r,x);
        }
        pushup(u);
    }
    int query(int u,int l,int r){
        if(t[u].l>=l&&t[u].r<=r){
            return t[u].max;
        }
        pushdown(u);
        int mid=(t[u].l+t[u].r)>>1,ret=-10251025;
        if(l<=mid){
            ret=max(ret,query(u*2,l,r));
        }
        if(r>mid){
            ret=max(ret,query(u*2+1,l,r));
        }
        return ret;
    }
}tree;
signed main(){
    cin>>n>>m;
    for(int i=1;i<=n;i++){
        cin>>c[i],c[i]+=c[i-1];
    }
    for(int i=1;i<=m;i++){
        cin>>a[i].l>>a[i].r>>a[i].p,vec[a[i].l].push_back({a[i].r,a[i].p});
    }
    sort(a+1,a+m+1,cmp);
    tree.build(1,1,n);
    for(int i=n;i>=1;i--){
        tmp+=c[i-1],tmp-=c[i];
        if(i+1<=n){
            tree.modify(1,i+1,n,c[i-1]-c[i]);
        }
        for(auto [x,y]:vec[i]){
            tmp+=y;
            if(x+1<=n){
                tree.modify(1,x+1,n,y);
            }
        }
        dp[i]=max(dp[i],tmp);
        dp[i]=max(dp[i],tree.query(1,i,n));
        if(i>1){
            tree.modify(1,i-1,i-1,dp[i]);    
        }
    }
    cout<<dp[1];
}

