#include<bits/stdc++.h>
using namespace std;
const int N=2e5+5;
int T,n,a[N],pre[N];
int highbit(int x){
    if(!x){
        return -1;
    }
    return __lg(x);
}
struct rmq{
    int lowbit(int x){
        return __lg(x&-x);
    }
    int rmq[18][N/18+5],belong[N],l[N],r[N],size,block,mask[N];
    void build(){
        size=__lg(n)+1,block=n/size+(n%size!=0);
        for(int i=1;i<=block;i++){
            l[i]=(i-1)*size+1,r[i]=min(n,l[i]+size-1);
            int now=0;
            for(int j=l[i];j<=r[i];j++){
                while(now){
                    int top=highbit(now);
                    if(highbit(a[l[i]+top])>=highbit(a[j])){
                        break;
                    }
                    now-=(1<<top);
                }
                now+=(1<<(j-l[i])),mask[j]=now,belong[j]=(j-1)/size+1;
            }
            rmq[0][i]=highbit(a[lowbit(now)+l[i]]);
        }
        for(int i=1;i<18;i++){
            for(int j=1;j+(1<<i)-1<=block;j++){
                rmq[i][j]=max(rmq[i-1][j],rmq[i-1][j+(1<<(i-1))]);
            }
        }
    }
    int inside(int x,int y){
        return highbit(a[x+lowbit(mask[y]>>(x-l[belong[x]]))]);
    }
    int query(int x,int y){
        if(belong[x]==belong[y]){
            return inside(x,y);
        }
        int ret=inside(x,r[belong[x]]);
        ret=max(ret,inside(l[belong[y]],y));
        if(belong[x]+1<=belong[y]-1){
            int k=__lg(belong[y]-1-belong[x]-1+1);
            ret=max(ret,rmq[k][belong[x]+1]);
            ret=max(ret,rmq[k][belong[y]-1-(1<<k)+1]);
        }
        return ret;
    }
}rmq;
int main(){
    ios::sync_with_stdio(0),cin.tie(0),cout.tie(0);
    cin>>T;
    while(T--){
        int T;
        cin>>n>>T;
        for(int i=1;i<=n;i++){
            cin>>a[i];
        }
        reverse(a+1,a+n+1);
        for(int i=1;i<=n;i++){
            pre[i]=pre[i-1]^a[i];
        }
        rmq.build();
        for(int x;T--;){
            cin>>x;
            int ans=0,now=1;
            while(now<=n){
                int l=now,r=n,pos=-1025;
                while(l<=r){
                    int mid=(l+r)>>1;
                    if(rmq.query(now,mid)<highbit(x)){
                        l=mid+1,pos=mid;
                    }
                    else{
                        r=mid-1;
                    }
                }
                if(pos==-1025){
                    if(x<a[now]){
                        break;
                    }
                    x^=a[now],now++,ans++;
                }
                else{
                    //[now,pos]是一个区间
                    x^=pre[pos]^pre[now-1];
                    ans+=pos-now+1,now=pos+1;
                }
            }
            cout<<ans<<" ";
        }
        cout<<'\n';
    }
}

