struct rmq{
    int rmq[17][N/17+5],size,block,mask[N],l[N],r[N],id[17][N/17+5];
    int belong(int x){
        return (x-1)/size+1;
    }
    int lowbit(int x){
        return __lg(x&-x);
    }
    void build(){
        size=__lg(n)+1,block=n/size+(n%size!=0);
        for(int i=1;i<=block;i++){
            l[i]=(i-1)*size+1,r[i]=min(l[i]+size-1,n);
            int now=0;
            for(int j=l[i];j<=r[i];j++){
                while(now){
                    int top=__lg(now);
                    if(a[top+l[i]]>=a[j]){
                        break;
                    }
                    now-=(1<<top);
                }
                now+=(1<<(j-l[i])),mask[j]=now;
            }
            rmq[0][i]=a[lowbit(now)+l[i]],id[0][i]=lowbit(now)+l[i];
        }  
        for(int i=1;i<17;i++){
            for(int j=1;j+(1<<i)-1<=block;j++){
                rmq[i][j]=max(rmq[i-1][j],rmq[i-1][j+(1<<(i-1))]);
                if(rmq[i][j]==rmq[i-1][j]){
                    id[i][j]=id[i-1][j];
                }
                else{
                    id[i][j]=id[i-1][j+(1<<(i-1))];
                }
            }
        }
    }
    int inside(int x,int y){
        return x+lowbit(mask[y]>>(x-l[belong(y)]));
    } 
    void check(int &x,int y,int &id){
        x=max(x,a[y]);
        if(x==a[y]){
            id=y;
        }
    }
    int query(int x,int y){
        if(belong(x)==belong(y)){
            return inside(x,y);
        }
        int ans=a[inside(x,r[belong(x)])],ret=inside(x,r[belong(x)]);
        check(ans,inside(l[belong(y)],y),ret);
        if(belong(x)+1<belong(y)){
            int k=__lg(belong(y)-1-belong(x)-1+1);
            check(ans,id[k][belong(x)+1],ret);
