#include<bits/stdc++.h>
using namespace std;
#define int long long
const int N=2e5+5,V=1e9;
int n,T,a[N],l[35],r[35],min1[35],min2[35],sum[35],num[35],tag[35],lim;
struct segtree{
    int root[N],node;
    segtree(){
        memset(root,0,sizeof(root)),node=0;
    }
    struct node{
        int l,r,num,sum;
        node(){
            l=r=num=sum=0;
        }
    }t[N*35];
    void clone(int &u){
        t[++node]=t[u],u=node;
    }
    void pushup(int u){
        t[u].num=t[t[u].l].num+t[t[u].r].num,t[u].sum=t[t[u].l].sum+t[t[u].r].sum;
    }
    void update(int &u,int l,int r,int x){
        clone(u);
        if(l==r){
            t[u].num++,t[u].sum+=x;
            return;
        }   
        int mid=(l+r)>>1;
        if(x<=mid){
            update(t[u].l,l,mid,x);
        }
        else{
            update(t[u].r,mid+1,r,x);
        }
        pushup(u);
    }
    int kth(int u1,int u2,int l,int r,int x){
        if(l==r){
            return l;
        }
        int num=t[t[u2].l].num-t[t[u1].l].num,mid=(l+r)>>1;
        if(num>=x){
            return kth(t[u1].l,t[u2].l,l,mid,x);
        }
        return kth(t[u1].r,t[u2].r,mid+1,r,x-num);
    }
    int sum(int u1,int u2,int l,int r,int L,int R){//查询的区间 实际的区间
        if(L>=l&&R<=r){
            return t[u2].sum-t[u1].sum;
        }
        if(l>r){
            return 0;
        }
        int mid=(L+R)>>1,ret=0;
        if(l<=mid){
            ret+=sum(t[u1].l,t[u2].l,l,r,L,mid);
        }
        if(r>mid){
            ret+=sum(t[u1].r,t[u2].r,l,r,mid+1,R);
        }
        return ret;
    }
    int num(int u1,int u2,int l,int r,int L,int R){//查询的区间 实际的区间
        if(L>=l&&R<=r){
            return t[u2].num-t[u1].num;
        }
        if(l>r){
            return 0;
        }
        int mid=(L+R)>>1,ret=0;
        if(l<=mid){
            ret+=num(t[u1].l,t[u2].l,l,r,L,mid);
        }
        if(r>mid){
            ret+=num(t[u1].r,t[u2].r,l,r,mid+1,R);
        }
        return ret;
    }
}tree;
void init(int low,int high){//我们需要最小值 以及和
    for(int i=1;i<=30;i++){
        num[i]=tree.num(tree.root[low-1],tree.root[high],l[i],r[i],1,V),sum[i]=tree.sum(tree.root[low-1],tree.root[high],l[i],r[i],1,V);
        min1[i]=min2[i]=-1;
        int val=tree.num(tree.root[low-1],tree.root[high],1,l[i]-1,1,V);
        if(num[i]>=1){
            min1[i]=tree.kth(tree.root[low-1],tree.root[high],1,V,val+1);
        }
        if(num[i]>=2){
            min2[i]=tree.kth(tree.root[low-1],tree.root[high],1,V,val+2);
        }
    }
}
void init(int low,int high,int x,int typ){//去除x的贡献 接下来还原
    for(int i=1;i<=30;i++){
        if(l[i]<=x&&x<=r[i]){
            if(!typ){//删除
                num[i]--,sum[i]-=x;
                if(min1[i]==x){
                    tag[i]=1;
                }
            }
            else{
                num[i]++,sum[i]+=x,tag[i]=0;
            }
        }
    }
}
int check(int l,int r,int mid){
    int x=tree.kth(tree.root[l-1],tree.root[r],1,V,mid);
    init(l,r,x,0);
    int size=x;
    for(int i=1;i<=30;i++){//我们需要最小值 以及和
        if(!num[i]){
            continue;
        }
        int tmp=min1[i];
        if(tag[i]){
            tmp=min2[i];
        }
        if(tmp==-1){
            continue;
        }
        if(size-lim<tmp){
            init(l,r,x,1);
            return 0;
        }
        size+=sum[i];
    }
    init(l,r,x,1);
    return 1;
}
