    for(int i=2;i<=30;i++){
        l[i]=r[i-1]+1,r[i]=2*l[i];
    }
    for(int i=1;i<=n;i++){
        tree.root[i]=tree.root[i-1],tree.update(tree.root[i],1,V,a[i]);
    }
    for(int l,r;T--;){
        cin>>l>>r>>lim,init(l,r);
        int low=1,high=r-l+1,ans=r-l+2;
        while(low<=high){
            int mid=(low+high)>>1;
            if(check(l,r,mid)){
                ans=mid,high=mid-1;
            }
            else{
                low=mid+1;
            }
        }
        cout<<r-l+1-ans+1<<'\n';
    }
}

