    ios::sync_with_stdio(0),cin.tie(0),cout.tie(0);
    cin>>n>>T>>vg>>vw>>vc;
    for(int i=1;i<=n;i++){
        cin>>a[i].x>>a[i].time;
        a[i].x=(a[i].x*vg+vw*a[i].time),dp[i]=1,a[i].time*=vc,vec.push_back(a[i].x-a[i].time),vec.push_back(a[i].x+a[i].time);
    }
    sort(a+1,a+n+1,cmp),cdq(1,n);
    for(int i=0;i<vec.size();i++){
        mp[vec[i]]=i+1;
    }
    for(int i=1;i<=T;i++){
        cin>>q[i].first,q[i].first*=vg,vec.push_back(q[i].first),q[i].second=i;
    }
    sort(vec.begin(),vec.end());
    for(int i=0;i<vec.size();i++){
        mp[vec[i]]=i+1;
    }
    for(int i=1;i<=n;i++){
        if(a[i].x-a[i].time<=a[i].x+a[i].time){
            segtree.update(segtree.root,mp[a[i].x-a[i].time],mp[a[i].x+a[i].time],dp[i],-V,V);
        }
    }
    for(int i=1;i<=T;i++){
        cout<<segtree.query(segtree.root,mp[q[i].first],-V,V)<<'\n';
    }
}

