void update(int r,int last,int num){
    for(int i=0;i<=num;i++){
        g[i]=(dp[last][i][0]+dp[last][i][1]+dp[last][i][2]);
    }
    for(int i=0;i<=n;i++){
        newf[i]=0;
    }
    for(int i=num;i>=0;i--){
        for(int j=n;j>=0;j--){
            if(i+j<=n){
                newf[i+j]=(newf[i+j]+g[i]*f[j])%mod;    
            }
        }
    }
    for(int i=0;i<=n;i++){
        f[i]=newf[i];
    }
}
