    for(int i=1;i<=n;i++){
        if(i%2){
            ans=(ans-C(n,i)*calc(i))%mod;
        }
        else{
            ans=(ans+C(n,i)*calc(i))%mod;
        }
    }
    cout<<(ans%mod+mod)%mod;
}

