int lca(int u,int v){
    while(u!=v){
        if(depth[u]<depth[v]){
            v=f[v];
        }
        else{
            u=f[u];
        }
    }
    return u;
}
void dfs(int u,int last){
    depth[u]=depth[last]+1,f[u]=last;
    for(int v:g[u]){
        if(v!=last){
            dfs(v,u);
        }
    }
}
void color(int u,int v){
    if(lca(u,v)!=u&&lca(u,v)!=v){
        color(u,lca(u,v)),color(v,lca(u,v));
        return;
    }
    if(depth[v]>depth[u]){
        swap(u,v);
    }
    if(u==v){
        return;
    }
    while(u!=v){
        b[id[u][f[u]]]=1;
        u=f[u];
    }
}
