#include<bits/stdc++.h>
using namespace std;
#define int long long
const int N=2e4+5,M=1e2+5;
int n,m,d[N],c[N],s[N],w[N],dp[N][M],sum[N];//我们给第i个村庄 分配了第j个基站 且恰好最后一个就在第i个村庄
int calc(int l,int r,int pos1,int pos2){
    int ret=0;
    for(int i=l;i<=r;i++){
        if(abs(d[i]-pos1)>s[i]&&abs(d[i]-pos2)>s[i]){
            ret+=w[i];
        }
    }
    return ret;
}
struct segtree{
    struct node{
        int l,r,min,plus;
    }t[N*4];
    void build(int u,int l,int r){
        t[u].l=l,t[u].r=r,t[u].min=1025102510251025,t[u].plus=0;
        if(l==r){
            return;
        }
        int mid=(l+r)>>1;
        build(u*2,l,mid),build(u*2+1,mid+1,r);
    }
    void pushup(int u){
        t[u].min=min(t[u*2].min,t[u*2+1].min);
    }
    void addplus(int u,int x){
        t[u].min+=x,t[u].plus+=x;
    }
    void pushdown(int u){
        addplus(u*2,t[u].plus),addplus(u*2+1,t[u].plus),t[u].plus=0;
    }
    int query(int u,int l,int r){
        if(t[u].l>=l&&t[u].r<=r){
            return t[u].min;
        }
        int mid=(t[u].l+t[u].r)>>1,ret=1025102510251025;
        if(l>r){
            return ret;
        }
        pushdown(u);
        if(l<=mid){
            ret=min(ret,query(u*2,l,r));
        }
        if(r>mid){
            ret=min(ret,query(u*2+1,l,r));
        }
        return ret;
    }
    void modify(int u,int l,int r,int x){
        if(t[u].l>=l&&t[u].r<=r){
            addplus(u,x);
            return;
        }
        pushdown(u);
        int mid=(t[u].l+t[u].r)>>1;
        if(l<=mid){
            modify(u*2,l,r,x);
        }
        if(r>mid){
            modify(u*2+1,l,r,x);
        }
        pushup(u);
    }
    void update(int u,int x,int val){
        if(t[u].l==t[u].r){
            t[u].min=val;
            return;
        }
        pushdown(u);
        int mid=(t[u].l+t[u].r)>>1;
        if(x<=mid){
            update(u*2,x,val);
        }
        else{
            update(u*2+1,x,val);
        }
        pushup(u);
    }
}tree[M];
signed main(){
    cin>>n>>m;
    for(int i=2;i<=n;i++){
        cin>>d[i];
    }
    for(int i=1;i<=n;i++){
        cin>>c[i];
    }
    for(int i=1;i<=n;i++){
        cin>>s[i];
    }
    for(int i=1;i<=n;i++){
        cin>>w[i],sum[i]=sum[i-1]+w[i];
    }
    for(int i=1;i<=m;i++){
        tree[i].build(1,1,n);
    }
    int ans=1025102510251025;
    priority_queue<pair<int,int>>q;
    for(int i=1;i<=n;i++){
        q.push({-d[i]-s[i],i});
        if(i>=2){//加入一些数字 他们
            while(q.size()&&d[i]>-q.top().first){
                int tmp=q.top().second;
                q.pop();
                //dk<dt-st
                int l=1,r=i-1,ret=-1025;
                while(l<=r){
                    int mid=(l+r)>>1;
                    if(d[mid]<d[tmp]-s[tmp]){
                        ret=mid,l=mid+1;
                    }
                    else{
                        r=mid-1;
                    }
                }
                if(ret!=-1025){
                    for(int j=1;j<=m;j++){
                        tree[j].modify(1,1,ret,w[tmp]);
                    }
                }
            }
        }
        dp[i][1]=calc(1,i,d[i],d[i])+c[i],tree[1].update(1,i,dp[i][1]);
        for(int j=2;j<=m;j++){
            dp[i][j]=c[i]+tree[j-1].query(1,1,i-1),tree[j].update(1,i,dp[i][j]);
        }
        int tmp=calc(i+1,n,d[i],d[i]);
        for(int j=1;j<=m;j++){
            ans=min(ans,dp[i][j]+tmp);
        }
    }
    cout<<min(sum[n],ans);
}

